package io.github.supermonster003.autojs6.plugin.threestoneai

import org.junit.Assert.assertEquals
import org.junit.Assert.assertFalse
import org.junit.Assert.assertTrue
import org.junit.Test
import java.io.File

/**
 * Guards the user-facing plugin instruction (plugin_instruction.md in the raw resource directories).
 *
 * The Markdown is generated by `.python/generate_markdown.py` from the `instruction_` keys of
 * `.readme/lang_*.json` and `.readme/template_plugin_instruction.md`; the generator's `--check`
 * mode covers drift. These tests keep the contract the plugin page relies on: every locale ships
 * an instruction, the raw provider protocol stays out of it, and the script examples use the
 * documented `ai` module of AutoJs6.
 */
class PluginInstructionCompatibilityTest {

    private val resourceRoot: File = listOf(
        File("src/main/res"),
        File("app/src/main/res"),
    ).firstOrNull(File::isDirectory)
        ?: error("Unable to locate the Android resource directory")

    @Test
    fun everyLocaleHasAGeneratedInstruction() {
        val files = instructionFiles()

        assertEquals(EXPECTED_DIRECTORIES, files.keys.sorted())
        assertEquals(
            "raw must mirror raw-en as the default locale",
            files.getValue("raw-en").readLines(),
            files.getValue("raw").readLines(),
        )
        files.forEach { (directory, file) ->
            val lines = file.readLines()
            assertTrue("$directory must not be empty", lines.any(String::isNotBlank))
            assertTrue(
                "$directory must not keep unrendered template placeholders",
                lines.none { line -> line.contains("{{") },
            )
        }
        assertTrue(
            "raw-zh must stay within the instruction size budget",
            files.getValue("raw-zh").length() <= ZH_HANS_BYTE_BUDGET,
        )
    }

    @Test
    fun instructionsDoNotExposeTheRawProviderProtocol() {
        instructionFiles().forEach { (directory, file) ->
            val lines = file.readLines()
            FORBIDDEN_MARKERS.forEach { marker ->
                assertTrue(
                    "$directory must not mention $marker",
                    lines.none { line -> line.contains(marker) },
                )
            }
            assertFalse(
                "$directory must not add a level-1 heading under the page title",
                lines.any { line -> line.startsWith("# ") },
            )
        }
    }

    @Test
    fun scriptExamplesUseTheDocumentedAiModule() {
        val files = instructionFiles()
        val reference = codeBlocks("raw-zh", files.getValue("raw-zh").readLines())

        assertTrue("Expected one to three code blocks", reference.size in 1..3)
        reference.forEach { block ->
            assertTrue("A code block must not exceed 15 lines", block.size <= 15)
        }
        val code = reference.flatten()
        DOCUMENTED_CALLS.forEach { call ->
            assertTrue(
                "The examples must use $call",
                code.any { line -> line.contains(call) },
            )
        }
        files.forEach { (directory, file) ->
            val lines = file.readLines()
            assertEquals(
                "$directory must share the code blocks of the template",
                reference,
                codeBlocks(directory, lines),
            )
            assertTrue(
                "$directory must link the AI chapter of the AutoJs6 documentation",
                lines.any { line -> line.contains(AI_DOCS_URL) },
            )
        }
    }

    private fun instructionFiles(): Map<String, File> = resourceRoot.listFiles()
        .orEmpty()
        .filter { directory ->
            directory.isDirectory &&
                (directory.name == "raw" || directory.name.startsWith("raw-"))
        }
        .map { directory -> directory.name to File(directory, INSTRUCTION_FILE_NAME) }
        .filter { (_, file) -> file.isFile }
        .toMap()

    private fun codeBlocks(label: String, lines: List<String>): List<List<String>> {
        val blocks = mutableListOf<List<String>>()
        var current: MutableList<String>? = null
        for (line in lines) {
            val block = current
            if (block == null) {
                if (line.startsWith(FENCE)) {
                    assertEquals("$label must fence code as js", JS_FENCE, line)
                    current = mutableListOf()
                }
            } else if (line == FENCE) {
                blocks.add(block.toList())
                current = null
            } else {
                block += line
            }
        }
        assertTrue("$label has an unclosed code block", current == null)
        return blocks
    }

    private companion object {
        const val INSTRUCTION_FILE_NAME = "plugin_instruction.md"
        const val AI_DOCS_URL = "https://docs.autojs6.com/#/ai"
        const val ZH_HANS_BYTE_BUDGET = 6L * 1024
        const val FENCE = "```"
        const val JS_FENCE = "```js"

        val EXPECTED_DIRECTORIES = listOf(
            "raw",
            "raw-ar",
            "raw-en",
            "raw-es",
            "raw-fr",
            "raw-ja",
            "raw-ko",
            "raw-ru",
            "raw-zh",
            "raw-zh-rHK",
            "raw-zh-rTW",
        ).sorted()

        val FORBIDDEN_MARKERS = listOf(
            "AiGenerationOptions",
            "CommonApi.",
            "TextApi.",
            "bindService",
            "Binder",
            "AIDL",
            "ProviderService",
        )

        val DOCUMENTED_CALLS = listOf(
            "ai.ask(",
            "ai.catalog(",
            "ai.session(",
            "session.close()",
        )
    }
}
